// recipe: openable-use
// args: name=s
// returns: ok, name, health, instant, keypad, minigame, max, bodyX, bodyY, error, detail
// Uses a locked crate the way the game's own path does, `Openable.OnUse` (`Openable.cs:8-31`), on the nearest
// openable that is neither instant nor a keypad. The pointer route is closed to the row — the game reads the mouse
// natively (`GetMouseButton*` have no IL body), so a staged click never reaches it (`.acceptance/lock-40`), and the
// OS-level input a real click would need is gated by `AcceptanceDriverGateTests`. The shortcut is named in the ticket.
((System.Func<string>)(() => { var culture = System.Globalization.CultureInfo.InvariantCulture; var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic; var cameraType = (System.Type)null; foreach (var assembly in System.AppDomain.CurrentDomain.GetAssemblies()) { var found = assembly.GetType("PlayerCamera", false); if (found != null) { cameraType = found; break; } } if (cameraType == null) { return "{\"ok\":false,\"error\":\"no-camera\"}"; } var camera = cameraType.GetField("main", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic)?.GetValue(null) ?? cameraType.GetProperty("main", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic)?.GetValue(null); var body = camera?.GetType().GetField("body", flags)?.GetValue(camera); if (body == null) { return "{\"ok\":false,\"error\":\"no-body\"}"; } var bodyPos = ((UnityEngine.Component)body).transform.position; var openableType = (System.Type)null; foreach (var assembly in System.AppDomain.CurrentDomain.GetAssemblies()) { var found = assembly.GetType("Openable", false); if (found != null) { openableType = found; break; } } if (openableType == null) { return "{\"ok\":false,\"error\":\"no-openable\"}"; } var wanted = {{s:name}} ?? ""; var best = (UnityEngine.Object)null; var bestScore = float.MaxValue; var bestName = ""; var bestHealth = 0f; foreach (var openable in UnityEngine.Object.FindObjectsOfType(openableType)) { var behaviour = openable as UnityEngine.MonoBehaviour; if (behaviour == null) { continue; } var instant = System.Convert.ToBoolean(openableType.GetField("instantOpen", flags)?.GetValue(openable), culture); var keypad = System.Convert.ToBoolean(openableType.GetField("isKeypad", flags)?.GetValue(openable), culture); if (instant || keypad) { continue; } var name = behaviour.name; if (wanted.Length > 0 && name.IndexOf(wanted, System.StringComparison.OrdinalIgnoreCase) < 0) { continue; } var health = 0f; var building = behaviour.GetComponent("BuildingEntity") as UnityEngine.MonoBehaviour; if (building != null) { var property = building.GetType().GetProperty("health", flags); var raw = property != null ? property.GetValue(building) : building.GetType().GetField("_health", flags)?.GetValue(building); health = raw != null ? System.Convert.ToSingle(raw, culture) : 0f; } var offset = behaviour.transform.position - bodyPos; var score = offset.sqrMagnitude; if (score < bestScore) { bestScore = score; best = openable; bestName = name; bestHealth = health; } } if (best == null) { return "{\"ok\":false,\"error\":\"no-openable-found\"}"; } var use = openableType.GetMethod("OnUse", flags); var failure = ""; if (use == null) { failure = "no-onuse"; } else { try { use.Invoke(best, null); } catch (System.Exception error) { failure = error.GetType().Name + ": " + error.Message; } } var minigame = "none"; var max = 0f; foreach (var assembly in System.AppDomain.CurrentDomain.GetAssemblies()) { var baseType = assembly.GetType("MinigameBase", false); if (baseType == null) { continue; } var main = baseType.GetField("main", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic)?.GetValue(null) ?? baseType.GetProperty("main", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic)?.GetValue(null); var current = main?.GetType().GetField("currentMinigame", flags)?.GetValue(main); if (current == null) { break; } minigame = current.GetType().Name; try { max = System.Convert.ToSingle(current.GetType().GetMethod("MaxTurnProgress", flags)?.Invoke(current, null), culture); } catch (System.Exception) { max = 0f; } break; } return "{\"ok\":true,\"name\":\"" + bestName.Replace("\"", "'") + "\",\"health\":" + bestHealth.ToString("0.###", culture) + ",\"minigame\":\"" +